        vendors: "ServiceNow, Jira Service Management, Freshservice", risk: "Major LMS outage during finals with no incident command workflow",
        stack: [{ name: "ServiceNow ITSM", role: "Workflow Engine", why: "ITIL-aligned incident, problem, change, and request management. The workflow core for university IT operations, used by small and large help desks.", href: "/vendors" }, { name: "Jira Service Management", role: "Alternative ITSM", why: "Used in universities with agile-oriented IT teams. Strong integration with development tools. Better for IT organizations that blend support with software development.", href: "/vendors" }],
